test("terminal routes exact global repo analysis before GestiaCore", () => {
    const terminal =
        fs.readFileSync(
            path.join(
                __dirname,
                "..",
                "gestia-terminal.html"
            ),
            "utf8"
        );

    const bypassIndex =
        terminal.indexOf("TERMINAL_LEGACY_REPO_BYPASS_41_19");

    const coreCallIndex =
        terminal.indexOf("await window.GestiaCore.procesarIntencion");

    assert.ok(bypassIndex > 0);
    assert.ok(coreCallIndex > bypassIndex);
    assert.match(
        terminal,
        /\(\?:analiza\|analizar\)\\s\+\(\?:el\\s\+\)\?\(\?:repo\|repositorio\)/
    );
    assert.match(terminal, /hasLegacyHumanRepoAction/);
    assert.match(terminal, /hasLegacyRepoTarget/);
    assert.match(terminal, /handled\s*=\s*true;[\s\S]{0,120}return;/);
});
